const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Rectangle([-70, -15, -50, -5]);  // Southern Brazilian Amazon

  const start2019 = '2019-01-01';
  const end2019 = '2019-12-31';
  const start2020 = '2020-01-01';
  const end2020 = '2020-12-31';

  // 2. Data Acquisition - VIIRS fire/hotspot data
  const viirs = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1');  // VIIRS 375m active fires

  const collection2019 = viirs
    .filterBounds(region)
    .filterDate(start2019, end2019);

  const collection2020 = viirs
    .filterBounds(region)
    .filterDate(start2020, end2020);

  // Check collection sizes
  const size2019 = collection2019.size().getInfo();
  const size2020 = collection2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  // Case C1: Empty collection
  if (size2019 === 0 || size2020 === 0) {
    console.log("C1");
    return;
  }

  // 3. Processing - Count fire pixels
  // Use 'MaxFRP' band (Fire Radiative Power) where > 0 indicates fire
  function countFirePixels(collection) {
    const fireCount = collection
      .select('MaxFRP')
      .map(img => img.gt(0))  // Binary mask: 1 for fire, 0 for non-fire
      .sum()  // Sum of all fire pixels across collection
      .rename('fire_count');

    return fireCount;
  }

  const fire2019 = countFirePixels(collection2019);
  const fire2020 = countFirePixels(collection2020);

  // 4. Calculate total fire pixel counts
  const count2019 = fire2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9,
  }).get('fire_count');

  const count2020 = fire2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9,
  }).get('fire_count');

  const val2019 = count2019.getInfo();
  const val2020 = count2020.getInfo();

  console.log(`2019 Fire pixels: ${val2019}`);
  console.log(`2020 Fire pixels: ${val2020}`);

  // Case C2: No valid pixels
  if (val2019 === 0 && val2020 === 0) {
    console.log("C2");
    return;
  }

  // Case C3: Invalid values
  if (val2019 === null || val2020 === null || 
      isNaN(val2019) || isNaN(val2020) ||
      val2019 < 0 || val2020 < 0) {
    console.log("C3");
    return;
  }

  // 5. Final comparison
  if (val2020 > val2019) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
